class Solution { private fun mirror(halfValue:Long,odd:Boolean):Long{var result=halfValue;var rest=if(odd)halfValue/10 else halfValue;while(rest>0){result=result*10+rest%10;rest/=10};return result};private fun cost(nums:IntArray,target:Long):Long{var total=0L;for(value in nums)total+=kotlin.math.abs(value.toLong()-target);return total};fun minimumCost(nums:IntArray):Long{nums.sort();val median=nums[nums.size/2].toLong();val text=median.toString();val length=text.length;val halfLength=(length+1)/2;val prefix=text.substring(0,halfLength).toLong();val candidates=hashSetOf(1L,999_999_999L);var power=1L;repeat(length){power*=10};candidates.add(power/10-1);candidates.add(power+1);for(delta in -1..1){val half=prefix+delta.toLong();if(half>0)candidates.add(mirror(half,length%2==1))};var answer=Long.MAX_VALUE;for(candidate in candidates)if(candidate>=1L&&candidate<1_000_000_000L)answer=minOf(answer,cost(nums,candidate));return answer} }
